// Worker entry for Cloudflare: the OpenNext app, the consumer of the background-job Queue, and the store.
// See src/lib/jobs.ts for why jobs go through a Queue, and docs/DEPLOY_CLOUDFLARE.md for the store.
// Generated by `opennextjs-cloudflare build`; this file is bundled by wrangler and left out of tsc (tsconfig.json).
import { DurableObject } from "cloudflare:workers";
import app from "../.open-next/worker.js";

type Fetcher = { fetch(input: RequestInfo, init?: RequestInit): Promise<Response> };
type R2Range = { offset?: number; length?: number; suffix?: number };
type R2Object = {
  key: string;
  size: number;
  httpEtag: string;
  range?: R2Range;
  customMetadata?: Record<string, string>;
  writeHttpMetadata(headers: Headers): void;
};
type R2ObjectBody = R2Object & { body: ReadableStream };
type R2Bucket = {
  get(key: string, options?: { range?: Headers; onlyIf?: Headers }): Promise<R2Object | R2ObjectBody | null>;
  head(key: string): Promise<R2Object | null>;
  put(
    key: string,
    value: ReadableStream | ArrayBuffer | null,
    options: { httpMetadata: { contentType: string }; customMetadata: Record<string, string>; sha256?: string },
  ): Promise<R2Object | null>;
  delete(key: string): Promise<void>;
  list(options: { cursor?: string; include?: string[] }): Promise<{ objects: R2Object[]; truncated: boolean; cursor?: string }>;
};
type ContainerApi = {
  running: boolean;
  start(options: { enableInternet: boolean; env: Record<string, string> }): void;
  monitor(): Promise<void>;
  getTcpPort(port: number): Fetcher;
  setInactivityTimeout(durationMs: number): Promise<void>;
  interceptOutboundHttp(addr: string, binding: Fetcher): Promise<void>;
};

type Env = {
  WORKER_SELF_REFERENCE: Fetcher;
  STORE: { getByName(name: string): Fetcher };
  STORE_FILES: R2Bucket;
  AUTH_SECRET: string;
  STORE_TOKEN: string;
  STORE_KEY_PASSWORD: string;
  GITHUB_ADMIN_TOKEN: string;
  NEXT_PUBLIC_STORE_URL: string;
};
type Message = { body: unknown; ack(): void };

/** The host the store container calls to keep its files in R2 (see store-server/app/mirror.py). */
const FILES_HOST = "store-files.internal";
const STORE_PORT = 8080;
/** How long the store stays up after its last request; the next request after that waits for a cold start. */
const STORE_IDLE_MS = 5 * 60 * 1000;
/** Restoring the files and `fdroid update` run before the store answers. */
const STORE_BOOT_MS = 3 * 60 * 1000;

const CONTENT_TYPES: Record<string, string> = {
  apk: "application/vnd.android.package-archive",
  jar: "application/java-archive",
  json: "application/json",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  webp: "image/webp",
  html: "text/html; charset=utf-8",
  css: "text/css",
  xml: "application/xml",
  yml: "text/yaml; charset=utf-8",
};

function contentType(key: string): string {
  return CONTENT_TYPES[key.split(".").pop()?.toLowerCase() ?? ""] ?? "application/octet-stream";
}

async function sameSecret(given: string | null, expected: string): Promise<boolean> {
  if (!given || !expected) return false;
  const digest = (s: string) => crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  const [a, b] = await Promise.all([digest(given), digest(expected)]);
  return (crypto.subtle as unknown as { timingSafeEqual(a: ArrayBuffer, b: ArrayBuffer): boolean }).timingSafeEqual(a, b);
}

/** The store's server: store-server/ in a container, its disk restored from R2 on every start. */
export class StoreContainer extends DurableObject<Env> {
  private booting?: Promise<void>;

  private get container(): ContainerApi {
    return (this.ctx as unknown as { container: ContainerApi }).container;
  }

  async fetch(request: Request): Promise<Response> {
    await this.boot();
    return this.container.getTcpPort(STORE_PORT).fetch(request);
  }

  private boot(): Promise<void> {
    if (!this.container.running) this.booting = undefined;
    this.booting ??= this.start().catch((e) => {
      this.booting = undefined;
      throw e;
    });
    return this.booting;
  }

  private async start(): Promise<void> {
    const c = this.container;
    if (!c.running) {
      c.start({
        enableInternet: true,
        env: {
          STORE_TOKEN: this.env.STORE_TOKEN,
          STORE_KEY_PASSWORD: this.env.STORE_KEY_PASSWORD,
          GITHUB_ADMIN_TOKEN: this.env.GITHUB_ADMIN_TOKEN,
          STORE_PUBLIC_URL: this.env.NEXT_PUBLIC_STORE_URL,
          STORE_MIRROR_URL: `http://${FILES_HOST}`,
        },
      });
      c.monitor().catch((e) => console.error("the store container stopped:", e));
    }
    await c.interceptOutboundHttp(FILES_HOST, this.env.WORKER_SELF_REFERENCE);
    await c.setInactivityTimeout(STORE_IDLE_MS);
    const port = c.getTcpPort(STORE_PORT);
    const deadline = Date.now() + STORE_BOOT_MS;
    for (;;) {
      try {
        if ((await port.fetch("http://store/healthz")).ok) return;
      } catch {
        // not listening yet
      }
      if (!c.running) throw new Error("the store container exited while starting");
      if (Date.now() > deadline) throw new Error("the store container did not start in time");
      await new Promise((r) => setTimeout(r, 500));
    }
  }
}

function storeStub(env: Env): Fetcher {
  return env.STORE.getByName("store");
}

/** Signing keys are written once: a container that lost them must never replace them with new ones. */
function isPrivate(key: string): boolean {
  return key.startsWith("keys/") || key === "fdroid/keystore.p12";
}

/** The mirror API store-server/app/mirror.py talks to, on top of R2. Only the store container reaches this host. */
async function storeFiles(request: Request, env: Env): Promise<Response> {
  if (!(await sameSecret(request.headers.get("x-store-token"), env.STORE_TOKEN))) {
    return new Response("invalid X-Store-Token", { status: 401 });
  }
  const { pathname } = new URL(request.url);
  if (pathname === "/list" && request.method === "GET") {
    const objects: { key: string; sha256: string | null }[] = [];
    let cursor: string | undefined;
    do {
      const page = await env.STORE_FILES.list({ cursor, include: ["customMetadata"] });
      for (const o of page.objects) objects.push({ key: o.key, sha256: o.customMetadata?.sha256 ?? null });
      cursor = page.truncated ? page.cursor : undefined;
    } while (cursor);
    return Response.json(objects);
  }
  if (!pathname.startsWith("/o/")) return new Response("not found", { status: 404 });
  const key = decodeURIComponent(pathname.slice(3));
  if (!key || key.split("/").some((part) => part === "" || part === "." || part === "..")) {
    return new Response("invalid key", { status: 400 });
  }
  switch (request.method) {
    case "GET": {
      const obj = await env.STORE_FILES.get(key);
      return obj && "body" in obj ? new Response(obj.body) : new Response("not found", { status: 404 });
    }
    case "PUT": {
      const sha256 = request.headers.get("x-content-sha256") ?? "";
      if (!/^[0-9a-f]{64}$/.test(sha256)) return new Response("X-Content-SHA256 is required", { status: 400 });
      if (isPrivate(key)) {
        const existing = await env.STORE_FILES.head(key);
        if (existing && existing.customMetadata?.sha256 !== sha256) {
          return new Response(`${key} already exists and is never replaced`, { status: 409 });
        }
      }
      await env.STORE_FILES.put(key, await request.arrayBuffer(), {
        httpMetadata: { contentType: contentType(key) },
        customMetadata: { sha256 },
        sha256,
      });
      return new Response(null, { status: 204 });
    }
    case "DELETE":
      if (isPrivate(key)) return new Response(`${key} is never deleted`, { status: 403 });
      await env.STORE_FILES.delete(key);
      return new Response(null, { status: 204 });
    default:
      return new Response("method not allowed", { status: 405 });
  }
}

/** The public F-Droid repository (index, APKs, icons), straight from R2 so phones never wait for the container. */
async function fdroidFile(request: Request, env: Env, pathname: string): Promise<Response> {
  if (request.method !== "GET" && request.method !== "HEAD") return new Response("method not allowed", { status: 405 });
  const key = decodeURIComponent(pathname.slice(1));
  if (key.split("/").some((part) => part === "..")) return new Response("not found", { status: 404 });
  const obj = await env.STORE_FILES.get(key, { range: request.headers, onlyIf: request.headers });
  if (!obj) return new Response("not found", { status: 404 });

  const headers = new Headers();
  obj.writeHttpMetadata(headers);
  headers.set("etag", obj.httpEtag);
  headers.set("accept-ranges", "bytes");
  // The index changes on every publish; APKs and icons keep their names for good.
  const name = key.split("/").pop() ?? "";
  headers.set("cache-control", /^(index|entry)[.-]/.test(name) ? "no-cache" : "public, max-age=3600");
  if (!("body" in obj)) {
    return new Response(null, { status: request.headers.has("if-none-match") ? 304 : 412, headers });
  }
  let status = 200;
  const range = obj.range;
  if (range && request.headers.has("range")) {
    const offset = range.suffix !== undefined ? obj.size - range.suffix : (range.offset ?? 0);
    const length = range.suffix ?? range.length ?? obj.size - offset;
    headers.set("content-range", `bytes ${offset}-${offset + length - 1}/${obj.size}`);
    headers.set("content-length", String(length));
    status = 206;
  } else {
    headers.set("content-length", String(obj.size));
  }
  return new Response(request.method === "HEAD" ? null : obj.body, { status, headers });
}

const worker = {
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    const url = new URL(request.url);
    if (url.hostname === FILES_HOST) return storeFiles(request, env);
    if (url.pathname.startsWith("/fdroid/repo/") || url.pathname.startsWith("/fdroid/archive/")) {
      return fdroidFile(request, env, url.pathname);
    }
    // android/publish-store-app.sh uploads the store app here; the container checks X-Store-Token.
    if (url.pathname === "/_store/store-app" && request.method === "PUT") {
      return storeStub(env).fetch(new Request("http://store/store-app", request));
    }
    return app.fetch(request, env, ctx);
  },

  /** One job per message (max_batch_size 1). A failed job is recorded on its row, so it is not retried. */
  async queue(batch: { messages: Message[] }, env: Env) {
    for (const message of batch.messages) {
      const res = await env.WORKER_SELF_REFERENCE.fetch("https://apslop.internal/api/internal/jobs", {
        method: "POST",
        headers: { "content-type": "application/json", "x-apslop-job-token": env.AUTH_SECRET },
        body: JSON.stringify(message.body),
      });
      if (!res.ok) console.error(`job failed: ${res.status} ${await res.text()}`);
      message.ack();
    }
  },
};

export default worker;
